//! the object browser's category, a plain name, what it needs on a map and a feature idea, by moby class.

/// The object browser's categories: name, icon (kit::draw_icon), the class whose picture stands for it.
pub(super) const CATEGORIES: [(&str, &str, i32); 17] = [
    ("Enemies", "Death", 459),
    ("Bosses", "Warn", 1051),
    ("Creatures", "Decor", 270),
    ("Characters", "Help", 774),
    ("Machines", "Loadout", 11),
    ("Crates", "Objects", 500),
    ("Pickups", "Plus", 1134),
    ("Gadget points", "Rails", 803),
    ("Platforms & lifts", "Floor", 726),
    ("Doors & gates", "Wall", 1021),
    ("Switches & triggers", "Trigger", 830),
    ("Hazards", "Hot", 1261),
    ("Breakables", "Gaps", 729),
    ("Vehicles", "Ship", 660),
    ("Water", "Slippery", 855),
    ("Scenery", "Ground", 724),
    ("Effects", "Light", 855),
];

pub(super) const NEVER_SOLID: u8 = 1;
pub(super) const HIDE: u8 = 2;
pub(super) const NEEDS_LINK: u8 = 4;
pub(super) const NEEDS_PATH: u8 = 8;
pub(super) const NEEDS_GROUP: u8 = 16;
pub(super) const STORY_SIDE_EFFECTS: u8 = 32;
pub(super) const MOVES_ITSELF: u8 = 64;

/// One class: its number, category (index into [`CATEGORIES`]), name, flags, a feature idea, how it breaks (empty:
/// it does not) and what it is.
pub(super) struct Info {
    pub class: i32,
    pub category: u8,
    pub name: &'static str,
    pub flags: u8,
    #[allow(dead_code)]
    pub idea: &'static str,
    pub breaks: &'static str,
    pub about: &'static str,
}

impl Info {
    pub fn has(&self, flag: u8) -> bool { self.flags & flag != 0 }
    pub fn category_name(&self) -> &'static str { CATEGORIES[self.category as usize].0 }
}

/// What is known of class `class`.
pub(super) fn info(class: i32) -> Option<&'static Info> { OBJECTS.binary_search_by_key(&class, |i| i.class).ok().map(|k| &OBJECTS[k]) }

